.footer-col-title { font-size: .8rem; font-weight: 700; letter-spacing: .08em; text-transform: uppercase; color: #fff; margin-bottom: 1rem; }
.footer-links { display: flex; flex-direction: column; gap: .6rem; }
.footer-links a { font-size: .875rem; transition: color var(--transition); }
.footer-links a:hover { color: #fff; }
.footer-links a:focus-visible { outline: 2px solid var(--color-accent); outline-offset: 2px; border-radius: 2px; }

