  transition: background var(--transition);
}
.cart-close-btn:hover { background: var(--color-surface-alt); color: var(--color-text); }
.cart-close-btn:focus-visible { outline: 2px solid var(--color-accent); outline-offset: 2px; }

.cart-items { flex: 1; overflow-y: auto; padding: 1rem 1.5rem; }
.cart-empty { text-align: center; color: var(--color-text-muted); padding: 3rem 1rem; }
.cart-empty-icon { font-size: 3rem; margin-bottom: .75rem; }

.cart-item {
