  font-size: 2rem;
}
.cart-item-info { flex: 1; min-width: 0; }
.cart-item-name { font-size: .875rem; font-weight: 600; line-height: 1.4; }
.cart-item-variant { font-size: .78rem; color: var(--color-text-muted); }
.cart-item-pricing {
