}
.cart-item-price { font-size: .95rem; font-weight: 700; }
.qty-control {
  display: flex; align-items: center; gap: .35rem;
}
.qty-btn {
  width: 26px; height: 26px;
  border: 1px solid var(--color-border);
  border-radius: 50%;
  display: flex; align-items: center; justify-content: center;
