  padding: .9rem;
  background: var(--color-accent);
  color: #fff;
  border-radius: var(--radius-sm);
  font-size: .95rem;
  font-weight: 700;
  transition: background var(--transition);
}
.checkout-btn:hover { background: var(--color-accent-hover); }
.checkout-btn:focus-visible { outline: 2px solid var(--color-accent); outline-offset: 3px; }

/* ===== TOAST ===== */
.toast-region {
  position: fixed;
  bottom: 1.5rem; right: 1.5rem;
  z-index: 300;
  display: flex;
  flex-direction: column;
  gap: .5rem;
  pointer-events: none;
}
.toast {
  background: var(--color-text);
  color: #fff;
  padding: .75rem 1.25rem;
  border-radius: var(--radius-sm);
  font-size: .875rem;
  font-weight: 500;
  box-shadow: var(--shadow-lg);
  display: flex;
  align-items: center;
  gap: .5rem;
  animation: toastIn .3s ease, toastOut .3s ease 2.5s forwards;
  pointer-events: auto;
}
@keyframes toastIn { from { opacity: 0; transform: translateY(12px); } to { opacity: 1; transform: translateY(0); } }
@keyframes toastOut { from { opacity: 1; transform: translateY(0); } to { opacity: 0; transform: translateY(12px); } }

/* ===== RESPONSIVE ===== */
@media (max-width: 768px) {
  .hero-slide-inner { grid-template-columns: 1fr; gap: 2rem; padding: 3rem 1.5rem; }
  .hero-image-wrap { display: none; }
  .product-grid { grid-template-columns: repeat(auto-fill, minmax(180px, 1fr)); }
  .editorial-grid { grid-template-columns: 1fr; }
  .article-card-featured { grid-row: auto; }
  .header-nav { display: none; }
  .deal-card-wide { flex-direction: column; grid-column: 1; }
}

@media (max-width: 480px) {
  .newsletter-form { flex-direction: column; }
  .footer-top { grid-template-columns: 1fr; }
}

/* ===== FOCUS ===== */
:focus-visible {
  outline: 2px solid var(--color-accent);
  outline-offset: 2px;
}
