/* ===== RESET & BASE ===== */
*, *::before, *::after { box-sizing: border-box; margin: 0; padding: 0; }

:root {
  --color-bg: #fafaf9;
  --color-surface: #ffffff;
  --color-surface-alt: #f4f3f0;
  --color-border: #e5e4e0;
  --color-text: #1a1917;
  --color-text-muted: #6b6a66;
  --color-accent: #d4521a;
  --color-accent-hover: #b84413;
  --color-accent-light: #fef2ec;
  --color-success: #1a7a4a;
  --color-deal: #c0392b;
  --font-sans: 'Inter', system-ui, -apple-system, sans-serif;
  --font-serif: 'Playfair Display', Georgia, serif;
  --radius-sm: 6px;
  --radius-md: 12px;
  --radius-lg: 20px;
  --shadow-sm: 0 1px 3px rgba(0,0,0,.07), 0 1px 2px rgba(0,0,0,.05);
  --shadow-md: 0 4px 16px rgba(0,0,0,.09);
  --shadow-lg: 0 12px 40px rgba(0,0,0,.12);
  --transition: 200ms ease;
  --max-width: 1280px;
}

html { scroll-behavior: smooth; }

body {
  font-family: var(--font-sans);
  background: var(--color-bg);
  color: var(--color-text);
  font-size: 1rem;
  line-height: 1.6;
  -webkit-font-smoothing: antialiased;
}

a { color: inherit; text-decoration: none; }
img { display: block; max-width: 100%; }
button { cursor: pointer; font-family: inherit; border: none; background: none; }
ul, ol { list-style: none; }

/* ===== SKIP LINK ===== */
.skip-link {
  position: absolute;
  top: -60px;
  left: 1rem;
  z-index: 1000;
  padding: .6rem 1.2rem;
  background: var(--color-accent);
  color: #fff;
  border-radius: var(--radius-sm);
  font-weight: 600;
  transition: top var(--transition);
}
.skip-link:focus { top: 1rem; }

/* ===== HEADER ===== */
.site-header {
  position: sticky;
  top: 0;
  z-index: 100;
  background: var(--color-surface);
  border-bottom: 1px solid var(--color-border);
  backdrop-filter: blur(8px);
}

.header-top {
  background: var(--color-text);
  color: #fff;
  text-align: center;
  padding: .45rem 1rem;
  font-size: .8rem;
  letter-spacing: .04em;
}

.header-main {
  max-width: var(--max-width);
  margin: 0 auto;
  padding: 0 1.5rem;
  display: grid;
  grid-template-columns: 1fr auto 1fr;
  align-items: center;
  gap: 1rem;
  height: 64px;
}

.header-nav { display: flex; gap: 1.75rem; align-items: center; }
.header-nav a {
  font-size: .875rem;
  font-weight: 500;
  color: var(--color-text-muted);
  transition: color var(--transition);
  position: relative;
  padding-bottom: 2px;
}
.header-nav a::after {
  content: '';
  position: absolute;
  bottom: -2px; left: 0;
  width: 0; height: 2px;
  background: var(--color-accent);
  transition: width var(--transition);
}
.header-nav a:hover { color: var(--color-text); }
.header-nav a:hover::after { width: 100%; }
.header-nav a:focus-visible { outline: 2px solid var(--color-accent); outline-offset: 3px; border-radius: 2px; }

.site-logo {
  text-align: center;
  font-family: var(--font-serif);
  font-size: 1.6rem;
  font-weight: 700;
  letter-spacing: -.02em;
  color: var(--color-text);
}
.site-logo span { color: var(--color-accent); }

.header-actions {
  display: flex;
  justify-content: flex-end;
  align-items: center;
  gap: .5rem;
}

.icon-btn {
  display: flex;
  align-items: center;
  justify-content: center;
  width: 40px;
  height: 40px;
  border-radius: var(--radius-sm);
  color: var(--color-text-muted);
  transition: background var(--transition), color var(--transition);
}
.icon-btn:hover { background: var(--color-surface-alt); color: var(--color-text); }
.icon-btn:focus-visible { outline: 2px solid var(--color-accent); outline-offset: 2px; }

.cart-btn { position: relative; }
.cart-badge {
  position: absolute;
  top: 4px; right: 4px;
  background: var(--color-accent);
  color: #fff;
  font-size: .65rem;
  font-weight: 700;
  width: 16px; height: 16px;
  border-radius: 50%;
  display: flex; align-items: center; justify-content: center;
  line-height: 1;
}

/* ===== HERO ===== */
.hero {
  overflow: hidden;
  background: var(--color-text);
  position: relative;
  min-height: 580px;
  display: flex;
  align-items: center;
}

.hero-slides { position: relative; width: 100%; min-height: 580px; }

.hero-slide {
  position: absolute;
  inset: 0;
  display: flex;
  align-items: center;
  opacity: 0;
  transition: opacity .6s ease;
  pointer-events: none;
}
.hero-slide.active { opacity: 1; pointer-events: auto; }

.hero-slide-inner {
  max-width: var(--max-width);
  margin: 0 auto;
  padding: 4rem 1.5rem;
  width: 100%;
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: 3rem;
  align-items: center;
}

.hero-content { color: #fff; }
.hero-eyebrow {
  display: inline-block;
  font-size: .75rem;
  font-weight: 700;
  letter-spacing: .12em;
  text-transform: uppercase;
  color: var(--color-accent);
  background: rgba(212,82,26,.15);
  padding: .3rem .75rem;
  border-radius: 999px;
  margin-bottom: 1.25rem;
}
.hero-title {
  font-family: var(--font-serif);
  font-size: clamp(2rem, 4vw, 3.25rem);
  line-height: 1.15;
  margin-bottom: 1rem;
}
.hero-desc {
  font-size: 1.0625rem;
  color: rgba(255,255,255,.75);
  margin-bottom: 2rem;
  max-width: 38ch;
}
.hero-actions { display: flex; gap: .875rem; flex-wrap: wrap; }

.btn {
  display: inline-flex;
  align-items: center;
  gap: .45rem;
  padding: .75rem 1.5rem;
  border-radius: var(--radius-sm);
  font-size: .9rem;
  font-weight: 600;
  transition: background var(--transition), transform var(--transition), box-shadow var(--transition);
}
.btn:focus-visible { outline: 2px solid var(--color-accent); outline-offset: 3px; }
.btn:active { transform: scale(.98); }

.btn-primary {
  background: var(--color-accent);
  color: #fff;
}
.btn-primary:hover { background: var(--color-accent-hover); box-shadow: 0 4px 14px rgba(212,82,26,.35); }

.btn-ghost {
  background: rgba(255,255,255,.12);
  color: #fff;
  border: 1px solid rgba(255,255,255,.25);
}
.btn-ghost:hover { background: rgba(255,255,255,.2); }

.btn-outline {
  background: transparent;
  color: var(--color-accent);
  border: 1.5px solid var(--color-accent);
}
.btn-outline:hover { background: var(--color-accent-light); }

.hero-image-wrap {
  border-radius: var(--radius-lg);
  overflow: hidden;
  aspect-ratio: 4/3;
  background: var(--color-surface-alt);
  display: flex; align-items: center; justify-content: center;
}

.hero-image-wrap svg { width: 60%; opacity: .12; }

.hero-image-placeholder {
  width: 100%;
  height: 100%;
  background: linear-gradient(135deg, #2a2927 0%, #3d3b38 100%);
  display: flex;
  align-items: center;
  justify-content: center;
  font-size: 6rem;
}

.hero-controls {
  position: absolute;
  bottom: 1.5rem;
  left: 50%;
  transform: translateX(-50%);
  display: flex;
  gap: .5rem;
  align-items: center;
}

.hero-dot {
  width: 8px; height: 8px;
  border-radius: 50%;
  background: rgba(255,255,255,.35);
  transition: background var(--transition), width var(--transition);
  border: none;
  padding: 0;
}
.hero-dot.active {
  background: #fff;
  width: 24px;
  border-radius: 4px;
}
.hero-dot:focus-visible { outline: 2px solid var(--color-accent); outline-offset: 3px; }

/* ===== CATEGORIES STRIP ===== */
.categories-strip {
  background: var(--color-surface);
  border-bottom: 1px solid var(--color-border);
  padding: 1.5rem 0;
}
.categories-strip-inner {
  max-width: var(--max-width);
  margin: 0 auto;
  padding: 0 1.5rem;
  display: flex;
  gap: 1rem;
  overflow-x: auto;
  scrollbar-width: none;
}
.categories-strip-inner::-webkit-scrollbar { display: none; }

.cat-chip {
  display: flex;
  flex-direction: column;
  align-items: center;
  gap: .5rem;
  flex-shrink: 0;
  padding: .75rem 1.25rem;
  border-radius: var(--radius-md);
  border: 1.5px solid var(--color-border);
  background: var(--color-surface);
  font-size: .8rem;
  font-weight: 600;
  color: var(--color-text-muted);
  cursor: pointer;
  transition: border-color var(--transition), color var(--transition), background var(--transition);
  min-width: 80px;
  text-align: center;
}
.cat-chip:hover, .cat-chip.active {
  border-color: var(--color-accent);
  color: var(--color-accent);
  background: var(--color-accent-light);
}
.cat-chip:focus-visible { outline: 2px solid var(--color-accent); outline-offset: 2px; }
.cat-chip-icon { font-size: 1.5rem; line-height: 1; }

/* ===== SECTION COMMON ===== */
.section { padding: 4rem 0; }
.section-inner { max-width: var(--max-width); margin: 0 auto; padding: 0 1.5rem; }

.section-header {
  display: flex;
  align-items: flex-end;
  justify-content: space-between;
  margin-bottom: 2rem;
  gap: 1rem;
  flex-wrap: wrap;
}
.section-title {
  font-family: var(--font-serif);
  font-size: clamp(1.5rem, 3vw, 2rem);
  font-weight: 700;
  line-height: 1.2;
}
.section-subtitle {
  color: var(--color-text-muted);
  font-size: .9rem;
  margin-top: .25rem;
}
.view-all {
  display: inline-flex;
  align-items: center;
  gap: .3rem;
  font-size: .875rem;
  font-weight: 600;
  color: var(--color-accent);
  white-space: nowrap;
  transition: gap var(--transition);
}
.view-all:hover { gap: .55rem; }
.view-all:focus-visible { outline: 2px solid var(--color-accent); outline-offset: 3px; border-radius: 2px; }

/* ===== PRODUCT GRID ===== */
.product-grid {
  display: grid;
  grid-template-columns: repeat(auto-fill, minmax(240px, 1fr));
  gap: 1.5rem;
}

.product-card {
  background: var(--color-surface);
  border-radius: var(--radius-md);
  overflow: hidden;
  border: 1px solid var(--color-border);
  transition: box-shadow var(--transition), transform var(--transition);
  display: flex;
  flex-direction: column;
}
.product-card:hover { box-shadow: var(--shadow-md); transform: translateY(-3px); }

.product-image-wrap {
  position: relative;
  aspect-ratio: 1;
  background: var(--color-surface-alt);
  display: flex;
  align-items: center;
  justify-content: center;
  overflow: hidden;
  font-size: 4rem;
  cursor: pointer;
}
.product-image-wrap::after {
  content: '';
  position: absolute;
  inset: 0;
  background: rgba(0,0,0,0);
  transition: background var(--transition);
}
.product-card:hover .product-image-wrap::after { background: rgba(0,0,0,.04); }

.product-badge {
  position: absolute;
  top: .75rem;
  left: .75rem;
  z-index: 1;
  padding: .25rem .6rem;
  border-radius: 999px;
  font-size: .7rem;
  font-weight: 700;
  letter-spacing: .04em;
  text-transform: uppercase;
}
.badge-new { background: var(--color-text); color: #fff; }
.badge-sale { background: var(--color-deal); color: #fff; }
.badge-hot { background: #e67e22; color: #fff; }

.wishlist-btn {
  position: absolute;
  top: .75rem; right: .75rem;
  z-index: 1;
  width: 34px; height: 34px;
  background: var(--color-surface);
  border-radius: 50%;
  display: flex; align-items: center; justify-content: center;
  box-shadow: var(--shadow-sm);
  color: var(--color-text-muted);
  font-size: 1rem;
  transition: color var(--transition), background var(--transition);
}
.wishlist-btn:hover, .wishlist-btn[aria-pressed="true"] { color: var(--color-deal); background: #fff3f3; }
.wishlist-btn:focus-visible { outline: 2px solid var(--color-accent); outline-offset: 2px; }

.product-info {
  padding: 1rem 1.125rem 1.125rem;
  display: flex;
  flex-direction: column;
  gap: .35rem;
  flex: 1;
}
.product-brand { font-size: .75rem; font-weight: 600; color: var(--color-text-muted); text-transform: uppercase; letter-spacing: .06em; }
.product-name { font-size: .95rem; font-weight: 600; line-height: 1.4; }
.product-name a:focus-visible { outline: 2px solid var(--color-accent); outline-offset: 2px; border-radius: 2px; }

.product-rating {
  display: flex;
  align-items: center;
  gap: .35rem;
  font-size: .8rem;
  color: var(--color-text-muted);
}
.stars { color: #f59e0b; letter-spacing: .05em; }

.product-pricing {
  display: flex;
  align-items: baseline;
  gap: .5rem;
  margin-top: auto;
  padding-top: .35rem;
}
.price-current { font-size: 1.1rem; font-weight: 700; }
.price-original {
  font-size: .875rem;
  color: var(--color-text-muted);
  text-decoration: line-through;
}
.price-discount {
  font-size: .75rem;
  font-weight: 700;
  color: var(--color-deal);
  background: #fef2f2;
  padding: .15rem .45rem;
  border-radius: 999px;
}

.add-to-cart-btn {
  margin-top: .75rem;
  width: 100%;
  padding: .6rem 1rem;
  background: var(--color-text);
  color: #fff;
  border-radius: var(--radius-sm);
  font-size: .85rem;
  font-weight: 600;
  transition: background var(--transition), transform var(--transition);
  display: flex; align-items: center; justify-content: center; gap: .4rem;
}
.add-to-cart-btn:hover { background: var(--color-accent); }
.add-to-cart-btn:focus-visible { outline: 2px solid var(--color-accent); outline-offset: 2px; }
.add-to-cart-btn:active { transform: scale(.97); }
.add-to-cart-btn.added { background: var(--color-success); }

/* ===== DEALS ===== */
.deals-section { background: var(--color-surface-alt); }

.deals-grid {
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: 1.5rem;
}

@media (max-width: 768px) { .deals-grid { grid-template-columns: 1fr; } }

.deal-card {
  position: relative;
  border-radius: var(--radius-md);
  overflow: hidden;
  min-height: 280px;
  display: flex;
  align-items: flex-end;
  background: var(--color-text);
}

.deal-card-bg {
  position: absolute;
  inset: 0;
  display: flex;
  align-items: center;
  justify-content: flex-end;
  padding: 2rem;
  font-size: 8rem;
  pointer-events: none;
  opacity: .18;
}

.deal-card-content {
  position: relative;
  z-index: 1;
  padding: 2rem;
  color: #fff;
  width: 100%;
}

.deal-tag {
  display: inline-block;
  background: var(--color-deal);
  color: #fff;
  font-size: .7rem;
  font-weight: 700;
  letter-spacing: .1em;
  text-transform: uppercase;
  padding: .25rem .65rem;
  border-radius: 999px;
  margin-bottom: .75rem;
}

.deal-title {
  font-family: var(--font-serif);
  font-size: 1.6rem;
  line-height: 1.2;
  margin-bottom: .5rem;
}
.deal-desc { font-size: .875rem; color: rgba(255,255,255,.75); margin-bottom: 1.25rem; }

.countdown {
  display: flex;
  gap: .5rem;
  margin-bottom: 1.25rem;
  align-items: center;
}
.countdown-unit {
  background: rgba(255,255,255,.12);
  border: 1px solid rgba(255,255,255,.2);
  border-radius: var(--radius-sm);
  padding: .4rem .6rem;
  text-align: center;
  min-width: 48px;
}
.countdown-value {
  font-size: 1.4rem;
  font-weight: 700;
  line-height: 1;
  font-variant-numeric: tabular-nums;
}
.countdown-label { font-size: .6rem; text-transform: uppercase; color: rgba(255,255,255,.6); letter-spacing: .08em; }
.countdown-sep { font-size: 1.2rem; font-weight: 700; color: rgba(255,255,255,.5); align-self: center; margin-bottom: 10px; }

.deal-card-wide {
  grid-column: 1 / -1;
  flex-direction: row;
  align-items: center;
}
.deal-card-wide .deal-card-content { max-width: 480px; }

/* ===== EDITORIAL ===== */
.editorial-grid {
  display: grid;
  grid-template-columns: 2fr 1fr 1fr;
  gap: 1.5rem;
}

@media (max-width: 900px) { .editorial-grid { grid-template-columns: 1fr 1fr; } }
@media (max-width: 600px) { .editorial-grid { grid-template-columns: 1fr; } }

.article-card {
  border-radius: var(--radius-md);
  overflow: hidden;
  background: var(--color-surface);
  border: 1px solid var(--color-border);
  display: flex;
  flex-direction: column;
  transition: box-shadow var(--transition), transform var(--transition);
}
.article-card:hover { box-shadow: var(--shadow-md); transform: translateY(-3px); }

.article-image {
  aspect-ratio: 16/9;
  background: var(--color-surface-alt);
  display: flex;
  align-items: center;
  justify-content: center;
  font-size: 3rem;
  overflow: hidden;
  position: relative;
}

.article-image-featured { aspect-ratio: 4/3; font-size: 5rem; }

.article-image-overlay {
  position: absolute;
  inset: 0;
  background: linear-gradient(to top, rgba(0,0,0,.5), transparent);
}

.article-meta {
  display: flex;
  align-items: center;
  gap: .6rem;
  font-size: .75rem;
  color: var(--color-text-muted);
  flex-wrap: wrap;
}

.article-category {
  font-weight: 700;
  color: var(--color-accent);
  text-transform: uppercase;
  letter-spacing: .06em;
  font-size: .7rem;
}

.article-body { padding: 1.25rem; display: flex; flex-direction: column; gap: .5rem; flex: 1; }
.article-title { font-size: 1rem; font-weight: 700; line-height: 1.4; }
.article-title a:focus-visible { outline: 2px solid var(--color-accent); outline-offset: 2px; border-radius: 2px; }
.article-excerpt { font-size: .875rem; color: var(--color-text-muted); line-height: 1.6; flex: 1; }
.article-read-more {
  font-size: .8rem;
  font-weight: 600;
  color: var(--color-accent);
  display: inline-flex;
  align-items: center;
  gap: .3rem;
  margin-top: .5rem;
  transition: gap var(--transition);
}
.article-read-more:hover { gap: .55rem; }
.article-read-more:focus-visible { outline: 2px solid var(--color-accent); outline-offset: 2px; border-radius: 2px; }

/* FEATURED ARTICLE */
.article-card-featured { grid-row: span 2; }
.article-card-featured .article-title { font-family: var(--font-serif); font-size: 1.4rem; }

/* ===== PROMO BANNER ===== */
.promo-banner {
  background: linear-gradient(135deg, var(--color-accent) 0%, #a8390f 100%);
  padding: 4rem 1.5rem;
  text-align: center;
  color: #fff;
}
.promo-banner-inner { max-width: 640px; margin: 0 auto; }
.promo-banner-eyebrow { font-size: .75rem; font-weight: 700; letter-spacing: .15em; text-transform: uppercase; opacity: .8; margin-bottom: .75rem; }
.promo-banner-title { font-family: var(--font-serif); font-size: clamp(1.8rem, 4vw, 2.75rem); margin-bottom: .75rem; line-height: 1.2; }
.promo-banner-desc { font-size: 1rem; opacity: .85; margin-bottom: 2rem; }

.newsletter-form {
  display: flex;
  gap: .5rem;
  max-width: 420px;
  margin: 0 auto;
}
.newsletter-input {
  flex: 1;
  padding: .75rem 1rem;
  border-radius: var(--radius-sm);
  border: none;
  font-size: .9rem;
  font-family: inherit;
  outline: none;
}
.newsletter-input:focus { box-shadow: 0 0 0 3px rgba(255,255,255,.4); }
.newsletter-btn {
  padding: .75rem 1.25rem;
  background: var(--color-text);
  color: #fff;
  border-radius: var(--radius-sm);
  font-size: .875rem;
  font-weight: 600;
  white-space: nowrap;
  transition: background var(--transition);
}
.newsletter-btn:hover { background: #2d2b28; }
.newsletter-btn:focus-visible { outline: 2px solid #fff; outline-offset: 2px; }
.newsletter-fine-print { font-size: .75rem; opacity: .6; margin-top: .75rem; }

/* ===== TRUST BAR ===== */
.trust-bar {
  background: var(--color-surface);
  border-top: 1px solid var(--color-border);
  border-bottom: 1px solid var(--color-border);
  padding: 2rem 1.5rem;
}
.trust-bar-inner {
  max-width: var(--max-width);
  margin: 0 auto;
  display: grid;
  grid-template-columns: repeat(auto-fit, minmax(180px, 1fr));
  gap: 1.5rem;
  text-align: center;
}
.trust-item { display: flex; flex-direction: column; align-items: center; gap: .5rem; }
.trust-icon { font-size: 1.75rem; }
.trust-title { font-size: .875rem; font-weight: 700; }
.trust-desc { font-size: .78rem; color: var(--color-text-muted); }

/* ===== FOOTER ===== */
.site-footer {
  background: var(--color-text);
  color: rgba(255,255,255,.75);
  padding: 4rem 1.5rem 2rem;
}
.footer-inner {
  max-width: var(--max-width);
  margin: 0 auto;
}
.footer-top {
  display: grid;
  grid-template-columns: 2fr 1fr 1fr 1fr;
  gap: 3rem;
  padding-bottom: 3rem;
  border-bottom: 1px solid rgba(255,255,255,.1);
  margin-bottom: 2rem;
}

@media (max-width: 900px) { .footer-top { grid-template-columns: 1fr 1fr; } }
@media (max-width: 560px) { .footer-top { grid-template-columns: 1fr; gap: 2rem; } }

.footer-brand .site-logo { color: #fff; font-size: 1.4rem; margin-bottom: .75rem; }
.footer-tagline { font-size: .875rem; line-height: 1.7; max-width: 32ch; }
.footer-social { display: flex; gap: .75rem; margin-top: 1.25rem; }
.social-link {
  width: 36px; height: 36px;
  border-radius: var(--radius-sm);
  background: rgba(255,255,255,.1);
  display: flex; align-items: center; justify-content: center;
  font-size: .9rem;
  transition: background var(--transition);
  color: #fff;
}
.social-link:hover { background: var(--color-accent); }
.social-link:focus-visible { outline: 2px solid var(--color-accent); outline-offset: 2px; }

.footer-col-title { font-size: .8rem; font-weight: 700; letter-spacing: .08em; text-transform: uppercase; color: #fff; margin-bottom: 1rem; }
.footer-links { display: flex; flex-direction: column; gap: .6rem; }
.footer-links a { font-size: .875rem; transition: color var(--transition); }
.footer-links a:hover { color: #fff; }
.footer-links a:focus-visible { outline: 2px solid var(--color-accent); outline-offset: 2px; border-radius: 2px; }

.footer-bottom {
  display: flex;
  justify-content: space-between;
  align-items: center;
  gap: 1rem;
  flex-wrap: wrap;
  font-size: .8rem;
}
.footer-legal { display: flex; gap: 1.25rem; flex-wrap: wrap; }
.footer-legal a { transition: color var(--transition); }
.footer-legal a:hover { color: #fff; }
.footer-legal a:focus-visible { outline: 2px solid var(--color-accent); outline-offset: 2px; border-radius: 2px; }
.payment-icons { display: flex; gap: .5rem; align-items: center; }
.payment-icon {
  background: rgba(255,255,255,.12);
  border: 1px solid rgba(255,255,255,.15);
  border-radius: 4px;
  padding: .2rem .5rem;
  font-size: .7rem;
  font-weight: 700;
  color: rgba(255,255,255,.8);
  letter-spacing: .04em;
}

