.cart-overlay {
  position: fixed;
  inset: 0;
  background: rgba(0,0,0,.5);
  z-index: 200;
  opacity: 0;
  pointer-events: none;
  transition: opacity .3s ease;
}
.cart-overlay.open { opacity: 1; pointer-events: auto; }

.cart-drawer {
  position: fixed;
  top: 0; right: 0; bottom: 0;
  width: min(400px, 100vw);
  background: var(--color-surface);
  z-index: 201;
  transform: translateX(100%);
  transition: transform .3s ease;
  display: flex;
  flex-direction: column;
}
.cart-drawer.open { transform: translateX(0); }

.cart-drawer-header {
  display: flex;
  align-items: center;
  justify-content: space-between;
  padding: 1.25rem 1.5rem;
  border-bottom: 1px solid var(--color-border);
}
.cart-drawer-title { font-weight: 700; font-size: 1.1rem; }
.cart-close-btn {
  display: flex; align-items: center; justify-content: center;
  width: 36px; height: 36px;
  border-radius: var(--radius-sm);
  color: var(--color-text-muted);
  transition: background var(--transition);
}
.cart-close-btn:hover { background: var(--color-surface-alt); color: var(--color-text); }
.cart-close-btn:focus-visible { outline: 2px solid var(--color-accent); outline-offset: 2px; }

.cart-items { flex: 1; overflow-y: auto; padding: 1rem 1.5rem; }
.cart-empty { text-align: center; color: var(--color-text-muted); padding: 3rem 1rem; }
.cart-empty-icon { font-size: 3rem; margin-bottom: .75rem; }

.cart-item {
  display: flex;
  gap: 1rem;
  padding: 1rem 0;
  border-bottom: 1px solid var(--color-border);
}
.cart-item-thumb {
  width: 72px; height: 72px;
  background: var(--color-surface-alt);
  border-radius: var(--radius-sm);
  flex-shrink: 0;
  display: flex; align-items: center; justify-content: center;
  font-size: 2rem;
}
.cart-item-info { flex: 1; min-width: 0; }
.cart-item-name { font-size: .875rem; font-weight: 600; line-height: 1.4; }
.cart-item-variant { font-size: .78rem; color: var(--color-text-muted); }
.cart-item-pricing {
  display: flex; align-items: center; justify-content: space-between;
  margin-top: .5rem;
}
.cart-item-price { font-size: .95rem; font-weight: 700; }
.qty-control {
  display: flex; align-items: center; gap: .35rem;
}
.qty-btn {
  width: 26px; height: 26px;
  border: 1px solid var(--color-border);
  border-radius: 50%;
  display: flex; align-items: center; justify-content: center;
  font-size: .9rem;
  color: var(--color-text);
  transition: background var(--transition);
}
.qty-btn:hover { background: var(--color-surface-alt); }
.qty-btn:focus-visible { outline: 2px solid var(--color-accent); outline-offset: 2px; }
.qty-value { font-size: .875rem; font-weight: 600; min-width: 20px; text-align: center; }

.cart-footer {
  padding: 1.25rem 1.5rem;
  border-top: 1px solid var(--color-border);
}
.cart-subtotal {
  display: flex; justify-content: space-between;
  font-size: .95rem;
  margin-bottom: 1rem;
}
.cart-subtotal-label { color: var(--color-text-muted); }
.cart-subtotal-value { font-weight: 700; font-size: 1.1rem; }
.checkout-btn {
  width: 100%;
  padding: .9rem;
  background: var(--color-accent);
  color: #fff;
  border-radius: var(--radius-sm);
  font-size: .95rem;
  font-weight: 700;
  transition: background var(--transition);
}
.checkout-btn:hover { background: var(--color-accent-hover); }
.checkout-btn:focus-visible { outline: 2px solid var(--color-accent); outline-offset: 3px; }

/* ===== TOAST ===== */
.toast-region {
  position: fixed;
  bottom: 1.5rem; right: 1.5rem;
  z-index: 300;
  display: flex;
  flex-direction: column;
  gap: .5rem;
  pointer-events: none;
}
.toast {
  background: var(--color-text);
  color: #fff;
  padding: .75rem 1.25rem;
  border-radius: var(--radius-sm);
  font-size: .875rem;
  font-weight: 500;
  box-shadow: var(--shadow-lg);
  display: flex;
  align-items: center;
  gap: .5rem;
  animation: toastIn .3s ease, toastOut .3s ease 2.5s forwards;
  pointer-events: auto;
}
@keyframes toastIn { from { opacity: 0; transform: translateY(12px); } to { opacity: 1; transform: translateY(0); } }
@keyframes toastOut { from { opacity: 1; transform: translateY(0); } to { opacity: 0; transform: translateY(12px); } }

/* ===== RESPONSIVE ===== */
@media (max-width: 768px) {
  .hero-slide-inner { grid-template-columns: 1fr; gap: 2rem; padding: 3rem 1.5rem; }
  .hero-image-wrap { display: none; }
  .product-grid { grid-template-columns: repeat(auto-fill, minmax(180px, 1fr)); }
  .editorial-grid { grid-template-columns: 1fr; }
  .article-card-featured { grid-row: auto; }
  .header-nav { display: none; }
  .deal-card-wide { flex-direction: column; grid-column: 1; }
}

@media (max-width: 480px) {
  .newsletter-form { flex-direction: column; }
  .footer-top { grid-template-columns: 1fr; }
}

/* ===== FOCUS ===== */
:focus-visible {
  outline: 2px solid var(--color-accent);
  outline-offset: 2px;
}

