        <button class="wishlist-btn" data-wish-btn="${p.id}" onclick="toggleWishlist(${p.id})"
          aria-pressed="${inWish}" aria-label="${inWish ? "Remove from wishlist" : "Add to wishlist"}">
          ${inWish ? "❤️" : "🤍"}
        </button>
        <span aria-hidden="true" style="font-size:4rem">${p.emoji}</span>
      </div>
      <div class="product-info">
        <div class="product-brand">${p.brand}</div>
        <div class="product-name"><a href="#" onclick="return false;" aria-label="${p.name} by ${p.brand}">${p.name}</a></div>
        <div class="product-rating" aria-label="Rated ${p.rating} out of 5, ${p.reviews} reviews">
          <span class="stars" aria-hidden="true">${starsHTML(p.rating)}</span>
          <span>${p.rating} (${p.reviews.toLocaleString()})</span>
        </div>
        <div class="product-pricing">
          <span class="price-current" aria-label="Current price: ${fmt(p.price)}">${fmt(p.price)}</span>
          ${p.originalPrice ? `<span class="price-original" aria-label="Original price: ${fmt(p.originalPrice)}">${fmt(p.originalPrice)}</span>` : ""}
          ${p.discount ? `<span class="price-discount" aria-label="${p.discount}% off">-${p.discount}%</span>` : ""}
        </div>
        <button class="add-to-cart-btn" data-add-btn="${p.id}" onclick="addToCart(${p.id})" aria-label="Add ${p.name} to cart">
