function fmt(n) { return new Intl.NumberFormat("en-US", { style: "currency", currency: "USD", minimumFractionDigits: 0 }).format(n); }

function showToast(msg, icon = "✓") {
  const region = $("#toast-region");
  const toast = document.createElement("div");
  toast.className = "toast";
  toast.setAttribute("role", "status");
  toast.setAttribute("aria-live", "polite");
  toast.innerHTML = `<span aria-hidden="true">${icon}</span> ${msg}`;
  region.appendChild(toast);
  setTimeout(() => toast.remove(), 2900);
}

/* ===== CART ===== */
function addToCart(productId) {
  const product = products.find(p => p.id === productId);
  if (!product) return;
  const existing = state.cart.find(i => i.id === productId);
  if (existing) {
    existing.qty += 1;
  } else {
    state.cart.push({ ...product, qty: 1 });
  }
  renderCart();
  updateCartBadge();
  showToast(`${product.name} added to cart`, "🛒");

  // Button feedback
  const btn = $(`[data-add-btn="${productId}"]`);
  if (btn) {
    btn.classList.add("added");
    btn.textContent = "✓ Added";
    setTimeout(() => {
      btn.classList.remove("added");
      btn.innerHTML = `<span aria-hidden="true">+</span> Add to Cart`;
    }, 1500);
  }
}

function changeQty(productId, delta) {
  const item = state.cart.find(i => i.id === productId);
  if (!item) return;
  item.qty += delta;
  if (item.qty <= 0) state.cart = state.cart.filter(i => i.id !== productId);
  renderCart();
  updateCartBadge();
}

function updateCartBadge() {
  const total = state.cart.reduce((sum, i) => sum + i.qty, 0);
  const badge = $("#cart-badge");
  if (badge) {
    badge.textContent = total;
    badge.hidden = total === 0;
  }
}

function cartSubtotal() {
  return state.cart.reduce((sum, i) => sum + i.price * i.qty, 0);
}

function renderCart() {
  const itemsEl = $("#cart-items");
  const footerEl = $("#cart-footer");
  if (!itemsEl) return;

  if (state.cart.length === 0) {
    itemsEl.innerHTML = `
      <div class="cart-empty" role="status">
        <div class="cart-empty-icon" aria-hidden="true">🛒</div>
        <p>Your cart is empty.</p>
        <p style="font-size:.85rem;color:var(--color-text-muted);margin-top:.35rem">Add some items to get started!</p>
      </div>`;
    footerEl.hidden = true;
    return;
  }

  footerEl.hidden = false;
  itemsEl.innerHTML = state.cart.map(item => `
    <div class="cart-item" role="listitem">
      <div class="cart-item-thumb" aria-hidden="true">${item.emoji}</div>
      <div class="cart-item-info">
        <div class="cart-item-name">${item.name}</div>
        <div class="cart-item-variant">${item.brand}</div>
        <div class="cart-item-pricing">
          <span class="cart-item-price">${fmt(item.price * item.qty)}</span>
