            <span class="qty-value" aria-live="polite">${item.qty}</span>
            <button class="qty-btn" onclick="changeQty(${item.id}, 1)" aria-label="Increase quantity">+</button>
          </div>
        </div>
      </div>
    </div>`).join("");

  $("#cart-subtotal-value").textContent = fmt(cartSubtotal());
}

