    if (btn) { btn.setAttribute("aria-pressed", "false"); btn.setAttribute("aria-label", "Add to wishlist"); }
    showToast("Removed from wishlist", "🤍");
  } else {
    state.wishlist.add(productId);
    if (btn) { btn.setAttribute("aria-pressed", "true"); btn.setAttribute("aria-label", "Remove from wishlist"); }
    showToast("Saved to wishlist", "❤️");
  }
}

/* ===== HERO SLIDER ===== */
function goToSlide(idx) {
  const slides = $$(".hero-slide");
  const dots = $$(".hero-dot");
  slides.forEach((s, i) => { s.classList.toggle("active", i === idx); s.setAttribute("aria-hidden", i !== idx ? "true" : "false"); });
  dots.forEach((d, i) => { d.classList.toggle("active", i === idx); d.setAttribute("aria-current", i === idx ? "true" : "false"); });
  state.currentSlide = idx;
}

function nextSlide() {
  goToSlide((state.currentSlide + 1) % heroSlides.length);
}

function startSlider() {
  state.slideInterval = setInterval(nextSlide, 5000);
}

function pauseSlider() {
  clearInterval(state.slideInterval);
