  wishlist: new Set(),
  cartOpen: false,
  activeCategory: "all",
  currentSlide: 0,
  slideInterval: null,
};

/* ===== HELPERS ===== */
function $(sel, ctx = document) { return ctx.querySelector(sel); }
function $$(sel, ctx = document) { return [...ctx.querySelectorAll(sel)]; }
function fmt(n) { return new Intl.NumberFormat("en-US", { style: "currency", currency: "USD", minimumFractionDigits: 0 }).format(n); }

function showToast(msg, icon = "✓") {
  const region = $("#toast-region");
  const toast = document.createElement("div");
  toast.className = "toast";
  toast.setAttribute("role", "status");
  toast.setAttribute("aria-live", "polite");
  toast.innerHTML = `<span aria-hidden="true">${icon}</span> ${msg}`;
  region.appendChild(toast);
  setTimeout(() => toast.remove(), 2900);
}

/* ===== CART ===== */
function addToCart(productId) {
  const product = products.find(p => p.id === productId);
  if (!product) return;
  const existing = state.cart.find(i => i.id === productId);
  if (existing) {
    existing.qty += 1;
  } else {
    state.cart.push({ ...product, qty: 1 });
  }
  renderCart();
  updateCartBadge();
  showToast(`${product.name} added to cart`, "🛒");

  // Button feedback
  const btn = $(`[data-add-btn="${productId}"]`);
  if (btn) {
    btn.classList.add("added");
    btn.textContent = "✓ Added";
    setTimeout(() => {
      btn.classList.remove("added");
      btn.innerHTML = `<span aria-hidden="true">+</span> Add to Cart`;
    }, 1500);
  }
}

function changeQty(productId, delta) {
  const item = state.cart.find(i => i.id === productId);
  if (!item) return;
  item.qty += delta;
  if (item.qty <= 0) state.cart = state.cart.filter(i => i.id !== productId);
  renderCart();
  updateCartBadge();
}

function updateCartBadge() {
  const total = state.cart.reduce((sum, i) => sum + i.qty, 0);
  const badge = $("#cart-badge");
  if (badge) {
    badge.textContent = total;
    badge.hidden = total === 0;
  }
}

function cartSubtotal() {
  return state.cart.reduce((sum, i) => sum + i.price * i.qty, 0);
}

function renderCart() {
  const itemsEl = $("#cart-items");
  const footerEl = $("#cart-footer");
  if (!itemsEl) return;

  if (state.cart.length === 0) {
    itemsEl.innerHTML = `
      <div class="cart-empty" role="status">
        <div class="cart-empty-icon" aria-hidden="true">🛒</div>
        <p>Your cart is empty.</p>
        <p style="font-size:.85rem;color:var(--color-text-muted);margin-top:.35rem">Add some items to get started!</p>
      </div>`;
    footerEl.hidden = true;
    return;
  }

  footerEl.hidden = false;
  itemsEl.innerHTML = state.cart.map(item => `
    <div class="cart-item" role="listitem">
      <div class="cart-item-thumb" aria-hidden="true">${item.emoji}</div>
      <div class="cart-item-info">
        <div class="cart-item-name">${item.name}</div>
        <div class="cart-item-variant">${item.brand}</div>
        <div class="cart-item-pricing">
          <span class="cart-item-price">${fmt(item.price * item.qty)}</span>
          <div class="qty-control" role="group" aria-label="Quantity for ${item.name}">
            <button class="qty-btn" onclick="changeQty(${item.id}, -1)" aria-label="Decrease quantity">−</button>
            <span class="qty-value" aria-live="polite">${item.qty}</span>
            <button class="qty-btn" onclick="changeQty(${item.id}, 1)" aria-label="Increase quantity">+</button>
          </div>
        </div>
      </div>
    </div>`).join("");

  $("#cart-subtotal-value").textContent = fmt(cartSubtotal());
}

function openCart() {
  state.cartOpen = true;
  $(".cart-drawer").classList.add("open");
  $(".cart-overlay").classList.add("open");
  $(".cart-drawer").setAttribute("aria-hidden", "false");
  document.body.style.overflow = "hidden";
  setTimeout(() => $("#cart-close-btn")?.focus(), 50);
}

function closeCart() {
  state.cartOpen = false;
  $(".cart-drawer").classList.remove("open");
  $(".cart-overlay").classList.remove("open");
  $(".cart-drawer").setAttribute("aria-hidden", "true");
  document.body.style.overflow = "";
  $("#cart-btn")?.focus();
}

/* ===== WISHLIST ===== */
function toggleWishlist(productId) {
  const btn = $(`[data-wish-btn="${productId}"]`);
  if (state.wishlist.has(productId)) {
    state.wishlist.delete(productId);
    if (btn) { btn.setAttribute("aria-pressed", "false"); btn.setAttribute("aria-label", "Add to wishlist"); }
    showToast("Removed from wishlist", "🤍");
  } else {
    state.wishlist.add(productId);
    if (btn) { btn.setAttribute("aria-pressed", "true"); btn.setAttribute("aria-label", "Remove from wishlist"); }
    showToast("Saved to wishlist", "❤️");
  }
}

/* ===== HERO SLIDER ===== */
function goToSlide(idx) {
  const slides = $$(".hero-slide");
  const dots = $$(".hero-dot");
  slides.forEach((s, i) => { s.classList.toggle("active", i === idx); s.setAttribute("aria-hidden", i !== idx ? "true" : "false"); });
  dots.forEach((d, i) => { d.classList.toggle("active", i === idx); d.setAttribute("aria-current", i === idx ? "true" : "false"); });
  state.currentSlide = idx;
}

function nextSlide() {
  goToSlide((state.currentSlide + 1) % heroSlides.length);
}

function startSlider() {
  state.slideInterval = setInterval(nextSlide, 5000);
}

function pauseSlider() {
  clearInterval(state.slideInterval);
}

/* ===== CATEGORY FILTER ===== */
function filterCategory(cat) {
  state.activeCategory = cat;
  $$(".cat-chip").forEach(c => {
    const active = c.dataset.cat === cat;
    c.classList.toggle("active", active);
    c.setAttribute("aria-pressed", active ? "true" : "false");
  });

  const filtered = cat === "all" ? products : products.filter(p => p.category === cat);
  const grid = $("#product-grid");
  if (grid) {
    grid.innerHTML = filtered.map(productCardHTML).join("");
    grid.setAttribute("aria-label", `${cat === "all" ? "All" : cat} products, ${filtered.length} items`);
  }
}

/* ===== RENDER HELPERS ===== */
function starsHTML(rating) {
  const full = Math.floor(rating);
  const half = rating % 1 >= 0.5 ? 1 : 0;
  const empty = 5 - full - half;
  return "★".repeat(full) + (half ? "½" : "") + "☆".repeat(empty);
}

function productCardHTML(p) {
  const inWish = state.wishlist.has(p.id);
  return `
    <article class="product-card" aria-label="${p.name}">
      <div class="product-image-wrap">
        ${p.badge ? `<span class="product-badge badge-${p.badge}" aria-label="${p.badge === "sale" ? "On Sale" : p.badge === "new" ? "New Arrival" : "Hot Item"}">${p.badge === "sale" ? "Sale" : p.badge === "new" ? "New" : "🔥 Hot"}</span>` : ""}
        <button class="wishlist-btn" data-wish-btn="${p.id}" onclick="toggleWishlist(${p.id})"
          aria-pressed="${inWish}" aria-label="${inWish ? "Remove from wishlist" : "Add to wishlist"}">
          ${inWish ? "❤️" : "🤍"}
        </button>
        <span aria-hidden="true" style="font-size:4rem">${p.emoji}</span>
      </div>
      <div class="product-info">
        <div class="product-brand">${p.brand}</div>
        <div class="product-name"><a href="#" onclick="return false;" aria-label="${p.name} by ${p.brand}">${p.name}</a></div>
        <div class="product-rating" aria-label="Rated ${p.rating} out of 5, ${p.reviews} reviews">
          <span class="stars" aria-hidden="true">${starsHTML(p.rating)}</span>
          <span>${p.rating} (${p.reviews.toLocaleString()})</span>
        </div>
        <div class="product-pricing">
          <span class="price-current" aria-label="Current price: ${fmt(p.price)}">${fmt(p.price)}</span>
          ${p.originalPrice ? `<span class="price-original" aria-label="Original price: ${fmt(p.originalPrice)}">${fmt(p.originalPrice)}</span>` : ""}
          ${p.discount ? `<span class="price-discount" aria-label="${p.discount}% off">-${p.discount}%</span>` : ""}
        </div>
        <button class="add-to-cart-btn" data-add-btn="${p.id}" onclick="addToCart(${p.id})" aria-label="Add ${p.name} to cart">
          <span aria-hidden="true">+</span> Add to Cart
        </button>
      </div>
    </article>`;
}

function renderHero() {
  const container = $("#hero-slides");
  if (!container) return;
  container.innerHTML = heroSlides.map((slide, i) => `
    <div class="hero-slide${i === 0 ? " active" : ""}" role="group" aria-roledescription="slide"
         aria-label="Slide ${i + 1} of ${heroSlides.length}: ${slide.eyebrow}" aria-hidden="${i !== 0}">
      <div class="hero-slide-inner" style="background:${slide.bg}">
        <div class="hero-content">
          <span class="hero-eyebrow">${slide.eyebrow}</span>
          <h1 class="hero-title">${slide.title.replace("\n", "<br>")}</h1>
          <p class="hero-desc">${slide.desc}</p>
          <div class="hero-actions">
            <a href="#featured" class="btn btn-primary">${slide.cta}</a>
            <a href="#editorial" class="btn btn-ghost">${slide.secondary}</a>
          </div>
        </div>
        <div class="hero-image-wrap" aria-hidden="true">
          <div class="hero-image-placeholder">${slide.emoji}</div>
        </div>
      </div>
    </div>`).join("");

  const controls = $("#hero-controls");
  controls.innerHTML = heroSlides.map((_, i) => `
    <button class="hero-dot${i === 0 ? " active" : ""}" onclick="goToSlide(${i})"
            aria-label="Go to slide ${i + 1}"
            aria-current="${i === 0 ? "true" : "false"}"></button>`).join("");
}

function renderCategories() {
  const container = $("#categories-strip");
  if (!container) return;
  container.innerHTML = categories.map(c => `
    <button class="cat-chip${c.id === "all" ? " active" : ""}" data-cat="${c.id}"
            onclick="filterCategory('${c.id}')"
            aria-pressed="${c.id === "all"}"
            aria-label="Filter by ${c.label}">
      <span class="cat-chip-icon" aria-hidden="true">${c.icon}</span>
      ${c.label}
    </button>`).join("");
}

function renderProducts() {
  const grid = $("#product-grid");
  if (!grid) return;
  grid.innerHTML = products.map(productCardHTML).join("");
}

function renderEditorial() {
  const grid = $("#editorial-grid");
  if (!grid) return;
  const featured = articles.find(a => a.featured);
  const rest = articles.filter(a => !a.featured);
  const allOrdered = [featured, ...rest].filter(Boolean);
  grid.innerHTML = allOrdered.map((a, idx) => `
    <article class="article-card${idx === 0 ? " article-card-featured" : ""}" aria-label="${a.title}">
      <div class="article-image${idx === 0 ? " article-image-featured" : ""}" aria-hidden="true">
        <span style="position:relative;z-index:1;font-size:${idx === 0 ? "5rem" : "3rem"}">${a.emoji}</span>
        <div class="article-image-overlay" aria-hidden="true"></div>
      </div>
      <div class="article-body">
        <div class="article-meta">
          <span class="article-category">${a.category}</span>
          <span aria-hidden="true">·</span>
          <time datetime="${a.date}">${a.date}</time>
          <span aria-hidden="true">·</span>
          <span>${a.readTime}</span>
        </div>
        <h3 class="article-title"><a href="#" onclick="return false;">${a.title}</a></h3>
        <p class="article-excerpt">${a.excerpt}</p>
        <a href="#" onclick="return false;" class="article-read-more" aria-label="Read more: ${a.title}">Read more <span aria-hidden="true">→</span></a>
      </div>
    </article>`).join("");
}

/* ===== COUNTDOWN ===== */
function renderCountdown(elementId, endTime) {
  function update() {
    const diff = Math.max(0, endTime - Date.now());
    const h = Math.floor(diff / 3600000);
    const m = Math.floor((diff % 3600000) / 60000);
    const s = Math.floor((diff % 60000) / 1000);
    const el = document.getElementById(elementId);
    if (el) {
      el.querySelector("[data-h]").textContent = String(h).padStart(2, "0");
      el.querySelector("[data-m]").textContent = String(m).padStart(2, "0");
      el.querySelector("[data-s]").textContent = String(s).padStart(2, "0");
    }
  }
  update();
  setInterval(update, 1000);
}

/* ===== NEWSLETTER ===== */
function handleNewsletter(e) {
  e.preventDefault();
  const input = e.target.querySelector(".newsletter-input");
  if (!input.value.trim()) return;
  showToast("Thanks for subscribing! 🎉", "📧");
  input.value = "";
}

/* ===== INIT ===== */
document.addEventListener("DOMContentLoaded", () => {
  renderHero();
  renderCategories();
  renderProducts();
  renderEditorial();
  renderCart();

  // Deals countdown — 6h 23m from now
  const dealEnd = Date.now() + (6 * 3600000 + 23 * 60000);
  renderCountdown("deal-countdown", dealEnd);

  // Hero slider
  startSlider();
  const hero = $(".hero");
  hero?.addEventListener("mouseenter", pauseSlider);
  hero?.addEventListener("mouseleave", startSlider);
  hero?.addEventListener("focusin", pauseSlider);
  hero?.addEventListener("focusout", startSlider);

  // Keyboard: escape closes cart
  document.addEventListener("keydown", e => {
    if (e.key === "Escape" && state.cartOpen) closeCart();
  });

  // Cart button
  document.getElementById("cart-btn")?.addEventListener("click", openCart);
  document.getElementById("cart-close-btn")?.addEventListener("click", closeCart);
  document.querySelector(".cart-overlay")?.addEventListener("click", closeCart);

  // Newsletter
  document.getElementById("newsletter-form")?.addEventListener("submit", handleNewsletter);

  // Focus trap in cart drawer
  document.querySelector(".cart-drawer")?.addEventListener("keydown", e => {
    if (e.key !== "Tab" || !state.cartOpen) return;
    const focusable = $$('button, [href], input, select, textarea, [tabindex]:not([tabindex="-1"])', e.currentTarget).filter(el => !el.disabled);
    const first = focusable[0], last = focusable[focusable.length - 1];
    if (e.shiftKey && document.activeElement === first) { e.preventDefault(); last?.focus(); }
    else if (!e.shiftKey && document.activeElement === last) { e.preventDefault(); first?.focus(); }
  });
});
