+  // Newsletter
+  document.getElementById("newsletter-form")?.addEventListener("submit", handleNewsletter);
+
+  // Focus trap in cart drawer
+  document.querySelector(".cart-drawer")?.addEventListener("keydown", e => {
+    if (e.key !== "Tab" || !state.cartOpen) return;
+    const focusable = $$('button, [href], input, select, textarea, [tabindex]:not([tabindex="-1"])', e.currentTarget).filter(el => !el.disabled);
+    const first = focusable[0], last = focusable[focusable.length - 1];
+    if (e.shiftKey && document.activeElement === first) { e.preventDefault(); last?.focus(); }
+    else if (!e.shiftKey && document.activeElement === last) { e.preventDefault(); first?.focus(); }
+  });
+});
